WFI.Data.add("quest", {
  [86574] = { "Rifornimenti per Stonetalon", "Raccogli $N1 Stonetalon Supplies dalle Pridewing Wyvern e consegnale all'Innkeeper Faralia.", "<Lo sfortunato corpo porta i segni di molti colpi delle viverne Pridewing. Lo zaino lì vicino è sgualcito e abbandonato, con il contenuto sparito, e solo un piccolo biglietto stretto nella mano del corriere indica cosa sia andato perduto: una spedizione destinata all'Innkeeper Faralia, allo Stonetalon Peak.>\n\n<Probabilmente le viverne hanno portato via i fagotti di provviste per foderarci i nidi.>", nil, nil, 0x91254c7f, 0x88cf623c, 0x25ddc985, nil, nil, "...mm" },
  [86585] = { "Lo stendardo dei caduti", "Innalza lo stendardo di Ironforge, sfida il trogg Headsplitter e uccidilo, poi fai rapporto al Captain Rugelfuss.", "La mountaineer caduta porta uno stendardo di Ironforge. Forse era in ricognizione, o stava compiendo una carica disperata. In ogni caso lo stendardo è stato gettato a terra e calpestato. La mountaineer è stata colpita alla testa così forte che le è saltato via l'elmo ed è stata uccisa sul colpo da un trogg, probabilmente con una clava chiodata.\n\nIl trogg che l'ha uccisa è probabilmente ancora nei paraggi e di sicuro ricorda lo stendardo. Innalzare di nuovo lo stendardo di Ironforge potrebbe richiamarlo.", "Quello stendardo sembra essere stato in guerra!", "Hai trovato il corpo di Ylva? Ah, poveretta. Diceva che avrebbe mostrato ai trogg che Ironforge non sarebbe mai caduta per mano loro. Era andata a cercare alcuni mountaineer mai tornati da una pattuglia nel territorio dei trogg. È sempre stata troppo indipendente per essere prudente. Ora sappiamo cosa è successo.\n\nRiprenderò lo stendardo e farò in modo che venga pulito ed esposto. Tu dovresti prendere la sua arma. Che ti serva bene contro i trogg.", 0xe9fba8e6, 0x55701efb, 0x9ae4d6b9, 0xe66f0ce2, 0x0c4098ad, "....." },
  [86757] = { "Rallentare l'avanzata degli orchi", "Porta $N1 Jagged Orc Swords e $N2 Curved Orc Daggers a Shandrina.", "Gli orchi hanno preso la foresta orientale, e i loro esploratori e soldati ora si aggirano per tutti i boschi! Per la nostra gente non è più sicuro muoversi per Ashenvale.\n\nDobbiamo respingere gli orchi e mettere in sicurezza la foresta. Siamo riuscite a eliminare alcuni soldati ed esploratori muovendoci con cautela ai margini del loro accampamento.\n\nCombatti gli orchi e portami le spade seghettate e i coltelli ricurvi che usano. Farò in modo che le loro armi siano recuperate e riutilizzate, così che niente vada sprecato.", nil, nil, 0xa5ae3f5b, 0xef062d38, 0xf54c066d, nil, nil, "...mm" },
  [86776] = { "Ingredienti per la forgia", "Porta $N1 Bronze Bars a Morhan Coppertongue.", "Thelsamar è un ottimo posto in cui vivere, ma non abbiamo tutte le comodità di Ironforge. Resto sempre senza bronzo! Mi serve altro bronzo se voglio continuare a fare attrezzi, bollitori e pentole!\n\nVedo che hai un po' di esperienza alla forgia. Pensi di potermi fondere qualche lingotto di bronzo? Posso pagarti bene!", "Bisogna tenere accese le forge!", "Ah, che sollievo! Ora dovrei riuscire a tenere accesa la forgia. Speriamo che uno di questi giorni un mercante cominci a portare regolarmente il carbone in città!", 0xd4a01b9a, 0x3fc9ca9a, 0x466409ef, 0xef5d24bd, 0xde5ced06, "....." },
})
